function buildCategoriasPadrao() {
  const categories = GRUPOS_PADRAO.map((g) => ({ ...g }));
  const descricoes = [];
  Object.entries(DESCRICOES_PADRAO).forEach(([categoriaId, nomes]) => nomes.forEach((nome) => descricoes.push({ id: uid(), nome, categoriaId })));
  return { categories, descricoes };
}
function grupoPadraoDe(tipo, nome) {
  const g = GRUPOS_PADRAO.find((x) => x.tipo === tipo && x.nome.toLowerCase() === String(nome).toLowerCase());
  if (g) return g.id;
  for (const [categoriaId, nomes] of Object.entries(DESCRICOES_PADRAO)) {
    const grupo = GRUPOS_PADRAO.find((x) => x.id === categoriaId);
    if (grupo.tipo === tipo && nomes.some((n) => n.toLowerCase() === String(nome).toLowerCase())) return categoriaId;
  }
  return null;
}
// Migra dados antigos (dezenas de categorias soltas) para: poucas categorias + lançamentos dentro delas.
function migrarCategoriasV2(d) {
  if (d._catV2) return d;
  const cats = [...(d.categories || [])];
  const existentes = new Set(cats.map((c) => c.id));
  GRUPOS_PADRAO.forEach((g) => { if (!existentes.has(g.id)) cats.push({ ...g }); });
  const gruposIds = new Set(GRUPOS_PADRAO.map((g) => g.id));
  const remap = {};
  const descricoes = [...(d.descricoes || [])];
  const manter = [];
  cats.forEach((c) => {
    if (gruposIds.has(c.id)) { manter.push(c); return; }
    const alvo = grupoPadraoDe(c.tipo, c.nome);
    if (!alvo) { manter.push(c); return; }
    remap[c.id] = alvo;
    const ehNomeDeGrupo = GRUPOS_PADRAO.some((g) => g.id === alvo && g.nome.toLowerCase() === String(c.nome).toLowerCase());
    if (!ehNomeDeGrupo && !descricoes.some((x) => x.categoriaId === alvo && x.nome.toLowerCase() === c.nome.toLowerCase())) descricoes.push({ id: uid(), nome: c.nome, categoriaId: alvo });
  });
  Object.entries(DESCRICOES_PADRAO).forEach(([categoriaId, nomes]) => nomes.forEach((nome) => {
    if (!descricoes.some((x) => x.categoriaId === categoriaId && x.nome.toLowerCase() === nome.toLowerCase())) descricoes.push({ id: uid(), nome, categoriaId });
  }));
  const transactions = (d.transactions || []).map((t) => (remap[t.categoriaId] ? { ...t, categoriaId: remap[t.categoriaId] } : t));
  const porCat = {};
  (d.budgets || []).forEach((b) => {
    const alvo = remap[b.categoriaId] || b.categoriaId;
    porCat[alvo] = porCat[alvo] ? { ...porCat[alvo], limite: Number(porCat[alvo].limite) + Number(b.limite) } : { ...b, categoriaId: alvo };
  });
  return { ...d, categories: manter, descricoes, transactions, budgets: Object.values(porCat), _catV2: true };
}
const ACCOUNT_TYPES = { corrente: "Conta Corrente", poupanca: "Poupança", investimento: "Investimento", cartao: "Cartão de Crédito", carteira: "Carteira / Dinheiro" };

// ==================== HELPERS ====================
function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }
function brl(n) { return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(n) || 0); }
function isoDate(d) { return d.toISOString().slice(0, 10); }
function fmtDate(iso) { if (!iso) return ""; const [y, m, d] = iso.split("-"); return `${d}/${m}/${y}`; }
function addDays(base, days) { const d = new Date(base); d.setDate(d.getDate() + days); return d; }
function generateSeries(startIso, count, freq) {
  const [y, m, d] = startIso.split("-").map(Number);
  const dates = [];
  for (let i = 0; i < count; i++) {
    let date;
    if (freq === "semanal") date = addDays(new Date(y, m - 1, d), i * 7);
    else if (freq === "anual") date = new Date(y + i, m - 1, d);
    else date = new Date(y, m - 1 + i, d);
    dates.push(isoDate(date));
  }
  return dates;
}
function seriesLabel(t) {
  if (t.parcelaTotal) return `${t.parcelaAtual}/${t.parcelaTotal}`;
  if (t.recorrente) return "Recorrente";
  return null;
}

// ---------- Importação de extrato (CSV / OFX) ----------
function parseValorBR(str) {
  if (typeof str === "number") return str;
  let s = String(str ?? "").trim();
  if (!s) return NaN;
  const neg = /^-/.test(s) || /^\(.*\)$/.test(s);
  s = s.replace(/[R$\s()]/g, "").replace(/^-/, "");
  if (s.includes(",") && s.includes(".")) s = s.replace(/\./g, "").replace(",", ".");
  else if (s.includes(",")) s = s.replace(",", ".");
  const n = parseFloat(s);
  if (isNaN(n)) return NaN;
  return neg ? -n : n;
}
function parseDataBR(str) {
  const s = String(str ?? "").trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
  m = s.match(/^(\d{8})$/);
  if (m) return `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`;
  return null;
}
function parseOFX(text) {
  const out = [];
  const blocks = text.split(/<STMTTRN>/i).slice(1);
  blocks.forEach((block) => {
    const get = (tag) => { const m = block.match(new RegExp(`<${tag}>([^<\r\n]+)`, "i")); return m ? m[1].trim() : ""; };
    const dtposted = get("DTPOSTED");
    const trnamt = get("TRNAMT");
    const memo = get("MEMO") || get("NAME");
    if (!dtposted || !trnamt) return;
    const data = parseDataBR(dtposted);
    const valorNum = parseFloat(trnamt.replace(",", "."));
    if (!data || isNaN(valorNum)) return;
    out.push({ data, descricao: memo || "Lançamento importado", valor: Math.abs(valorNum), tipo: valorNum >= 0 ? "receita" : "despesa" });
  });
  return out;
}

// Saldo de uma conta bancária = saldo inicial + soma dos lançamentos concluídos
// ligados a ela (que não estejam marcados como "não afeta saldo"). Nunca é editado
// diretamente — sempre calculado, pra nunca duplicar valor.
function computeSaldoConta(conta, transactions) {
  const soma = (transactions || [])
    .filter((t) => t.origemTipo === "conta" && t.origemId === conta.id && t.status === "concluido" && t.afetaSaldo !== false)
    .reduce((s, t) => s + (t.tipo === "receita" ? Number(t.valor) : -Number(t.valor)), 0);
  return Number(conta.saldoInicial || 0) + soma;
}
// Saldo de um investimento = saldo inicial + aportes + rendimentos - resgates,
// tudo separado por tipo de movimento (nunca mistura na hora de olhar o extrato).
function computeSaldoInvestimento(conta, movimentos) {
  const soma = (movimentos || [])
    .filter((m) => m.investId === conta.id)
    .reduce((s, m) => s + (m.tipo === "resgate" ? -Number(m.valor) : Number(m.valor)), 0);
  return Number(conta.saldoInicial || 0) + soma;
}
function resumoInvestimento(conta, movimentos) {
  const mov = (movimentos || []).filter((m) => m.investId === conta.id);
  const aportes = mov.filter((m) => m.tipo === "aporte").reduce((s, m) => s + Number(m.valor), 0);
  const rendimentos = mov.filter((m) => m.tipo === "rendimento").reduce((s, m) => s + Number(m.valor), 0);
  const resgates = mov.filter((m) => m.tipo === "resgate").reduce((s, m) => s + Number(m.valor), 0);
  return { aportes, rendimentos, resgates };
}
// Taxas anuais de referência (aproximadas) por tipo de investimento — ponto de
// partida sugerido, não são dados de mercado ao vivo. O usuário pode ajustar.
const TIPOS_INVESTIMENTO = {
  poupanca: { label: "Poupança", taxaRef: 6.17 },
  cdb: { label: "CDB / CDI", taxaRef: 10.65 },
  tesouro_selic: { label: "Tesouro Selic", taxaRef: 10.75 },
  tesouro_ipca: { label: "Tesouro IPCA+", taxaRef: 10.5 },
  acoes_fundos: { label: "Ações / Fundos", taxaRef: 0 },
  outro: { label: "Outro", taxaRef: 0 },
};
// Data do último movimento (ou saldoInicial se ainda não teve nenhum) — base
// pra contar quantos dias já se passaram sem lançar rendimento.
function dataBaseInvestimento(conta, movimentos) {
  const mov = (movimentos || []).filter((m) => m.investId === conta.id);
  if (mov.length === 0) return conta.criadaEm || isoDate(new Date());
  return mov.reduce((max, m) => (m.data > max ? m.data : max), mov[0].data);
}
// Rendimento estimado acumulado desde a última movimentação, em juros compostos,
// usando a taxa anual cadastrada na conta. Puramente uma estimativa — some
// automaticamente sobre o saldo atual (sem contar o que já foi lançado).
function rendimentoEstimado(conta, movimentos) {
  const taxaAnual = Number(conta.taxaAnual || 0);
  if (taxaAnual <= 0) return { valor: 0, dias: 0, desde: null };
  const desde = dataBaseInvestimento(conta, movimentos);
  const dias = Math.floor((new Date() - new Date(desde + "T00:00:00")) / 86400000);
  if (dias <= 0) return { valor: 0, dias: 0, desde };
  const saldoBase = computeSaldoInvestimento(conta, movimentos);
  const taxaDiaria = Math.pow(1 + taxaAnual / 100, 1 / 365) - 1;
  const valor = saldoBase * (Math.pow(1 + taxaDiaria, dias) - 1);
  return { valor, dias, desde };
}
// Evolução mensal do total investido (só a partir de quando cada investimento começou).
function evolucaoMensalInvest(contas, movimentos, meses = 6) {
  const hoje = new Date();
  const linhas = [];
  const inicios = (contas || []).map((c) => [c.criadaEm, ...(movimentos || []).filter((m) => m.investId === c.id).map((m) => m.data)].filter(Boolean).sort()[0]).filter(Boolean).sort();
  const mesInicio = inicios.length ? inicios[0].slice(0, 7) : isoDate(hoje).slice(0, 7);
  for (let i = meses - 1; i >= 0; i--) {
    const d = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
    const chave = isoDate(d).slice(0, 7);
    if (chave < mesInicio) continue;
    const fim = isoDate(new Date(d.getFullYear(), d.getMonth() + 1, 0));
    let total = 0, aportado = 0;
    (contas || []).forEach((c) => {
      const movs = (movimentos || []).filter((m) => m.investId === c.id && m.data <= fim);
      total += Number(c.saldoInicial || 0) + movs.reduce((s, m) => s + (m.tipo === "resgate" ? -Number(m.valor) : Number(m.valor)), 0);
      aportado += Number(c.saldoInicial || 0) + movs.filter((m) => m.tipo === "aporte").reduce((s, m) => s + Number(m.valor), 0) - movs.filter((m) => m.tipo === "resgate").reduce((s, m) => s + Number(m.valor), 0);
    });
    linhas.push({ mes: monthLabel(chave), total, aportado });
  }
  return linhas;
}
// Previsão de quando a meta será alcançada, no ritmo médio desde que foi criada.
function projetarConclusaoMeta(goal) {
  const alvo = Number(goal.valorAlvo || 0);
  const atual = Number(goal.valorAtual || 0);
  if (alvo <= 0) return { status: "sem-dados" };
  if (atual >= alvo) return { status: "concluida" };
  if (!goal.criadaEm) return { status: "sem-dados" };
  const hoje = new Date();
  const inicio = new Date(goal.criadaEm + "T00:00:00");
  const diasDecorridos = Math.max(1, Math.round((hoje - inicio) / 86400000));
  const ritmoDiario = atual / diasDecorridos;
  if (ritmoDiario <= 0) return { status: "sem-progresso" };
  const diasFaltando = Math.ceil((alvo - atual) / ritmoDiario);
  const dataPrevista = new Date(hoje.getTime() + diasFaltando * 86400000);
  const dentroDoPrazo = goal.prazo ? isoDate(dataPrevista) <= goal.prazo : null;
  return { status: "projetada", dataPrevista: isoDate(dataPrevista), diasFaltando, dentroDoPrazo, ritmoMensal: ritmoDiario * 30 };
}
// Saldo da conta no fim de cada um dos últimos N meses — o "sobrou" de um mês
// já entra automaticamente no mês seguinte, porque a soma é sempre acumulada.
function evolucaoMensalConta(conta, transactions, meses = 6) {
  const hoje = new Date();
  const linhas = [];
  const daConta = (transactions || []).filter((t) => t.origemTipo === "conta" && t.origemId === conta.id);
  // A conta só "existe" a partir do mês do saldo inicial (ou do primeiro lançamento, se for anterior).
  const datas = [conta.dataInicial, conta.criadaEm, ...daConta.map((t) => t.data)].filter(Boolean).sort();
  const mesInicio = datas.length ? datas[0].slice(0, 7) : isoDate(hoje).slice(0, 7);
  for (let i = meses - 1; i >= 0; i--) {
    const d = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
    const chave = isoDate(d).slice(0, 7);
    if (chave < mesInicio) continue;
    const fimDoMes = isoDate(new Date(d.getFullYear(), d.getMonth() + 1, 0));
    const soma = daConta
      .filter((t) => t.status === "concluido" && t.afetaSaldo !== false && t.data <= fimDoMes)
      .reduce((s, t) => s + (t.tipo === "receita" ? Number(t.valor) : -Number(t.valor)), 0);
    linhas.push({ mes: monthLabel(chave), saldo: Number(conta.saldoInicial || 0) + soma });
  }
  return linhas;
}
function resolveOrigemNome(t, contas, cartoes) {
  if (t.origemTipo === "conta") return (contas || []).find((c) => c.id === t.origemId)?.nome || t.origemTexto || "—";
  if (t.origemTipo === "cartao") return (cartoes || []).find((c) => c.id === t.origemId)?.nome || t.origemTexto || "—";
  return t.origemTexto || "—";
}

function computeAlerts(data) {
  const notif = data.settings?.notificacoes || { diasAntecedencia: 7, alertaVencido: true, alertaOrcamento: true, alertaSaldoBaixo: false, saldoMinimo: 0 };
  const today = isoDate(new Date());
  const currentMonth = today.slice(0, 7);
  const catById = Object.fromEntries(data.categories.map((c) => [c.id, c]));
  const vencidasList = data.transactions.filter((t) => t.status === "pendente" && t.data < today);
  const monthTx = data.transactions.filter((t) => t.data.slice(0, 7) === currentMonth);
  const orcamentoEstourado = notif.alertaOrcamento ? (data.budgets || []).filter((b) => {
    const gasto = monthTx.filter((t) => t.tipo === "despesa" && t.categoriaId === b.categoriaId).reduce((s, t) => s + Number(t.valor), 0);
    return gasto > Number(b.limite);
  }).map((b) => catById[b.categoriaId]?.nome).filter(Boolean) : [];
  const contasSaldoBaixo = notif.alertaSaldoBaixo ? (data.contas || []).filter((c) => computeSaldoConta(c, data.transactions) < Number(notif.saldoMinimo || 0)).map((c) => c.nome) : [];
  const items = [];
  if (notif.alertaVencido) vencidasList.forEach((t) => items.push({ tipo: "vencido", texto: `"${t.descricao}" venceu em ${fmtDate(t.data)}` }));
  orcamentoEstourado.forEach((nome) => items.push({ tipo: "orcamento", texto: `Orçamento de "${nome}" estourado este mês` }));
  contasSaldoBaixo.forEach((nome) => items.push({ tipo: "saldo", texto: `Saldo baixo em "${nome}"` }));
  return { items, vencidas: notif.alertaVencido ? vencidasList.length : 0, orcamentoEstourado, contasSaldoBaixo };
}
function monthLabel(key) {
  const [y, m] = key.split("-");
  const names = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
  return `${names[parseInt(m, 10) - 1]}/${y.slice(2)}`;
}
async function sha256(text) {
  const enc = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function resizeImage(file, maxSize = 160) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const scale = Math.min(1, maxSize / Math.max(img.width, img.height));
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/png"));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}
function downloadFile(filename, content, mime) {
  try {
    const blob = new Blob([content], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    return true;
  } catch (e) {
    return false;
  }
}
function toCSV(rows, headers) {
  const esc = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const lines = [headers.map(esc).join(";")];
  rows.forEach((r) => lines.push(r.map(esc).join(";")));
  return "\uFEFF" + lines.join("\r\n");
}

// Exporta uma planilha Excel real (.xlsx) usando SheetJS.
function exportExcel(filename, sheetTitle, subtitle, headers, rows, totals) {
  try {
    const aoa = [[sheetTitle], [subtitle], [], headers, ...rows];
    if (totals) aoa.push([], ...totals);
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws["!cols"] = headers.map(() => ({ wch: 20 }));
    ws["!merges"] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: headers.length - 1 } }, { s: { r: 1, c: 0 }, e: { r: 1, c: headers.length - 1 } }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Relatório");
    XLSX.writeFile(wb, filename);
    return true;
  } catch (e) {
    return false;
  }
}

// Exporta um documento que abre no Word, com formatação (cabeçalho, tabela, totais).
function exportWord(filename, logoSrc, title, subtitle, headers, rows, totalsHtml) {
  const theadCols = headers.map((h) => `<th style="background:#0f2547;color:#fff;padding:8px;border:1px solid #ccc;text-align:left;font-size:12px;">${h}</th>`).join("");
  const bodyRows = rows.map((r) => `<tr>${r.map((c) => `<td style="padding:7px 8px;border:1px solid #ddd;font-size:12px;">${c ?? ""}</td>`).join("")}</tr>`).join("");
  const html = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
    <head><meta charset="utf-8"><title>${title}</title></head>
    <body style="font-family:Calibri,Arial,sans-serif;color:#1c1c1c;">
      <table style="width:100%;border-collapse:collapse;margin-bottom:14px;"><tr>
        <td style="width:56px;"><img src="${logoSrc}" style="width:48px;height:48px;" /></td>
        <td><h1 style="margin:0;font-size:20px;color:#0f2547;">${title}</h1><p style="margin:2px 0 0;font-size:12px;color:#555;">${subtitle}</p></td>
      </tr></table>
      <table style="width:100%;border-collapse:collapse;">
        <thead><tr>${theadCols}</tr></thead>
        <tbody>${bodyRows}</tbody>
      </table>
      ${totalsHtml || ""}
      <p style="font-size:10px;color:#999;margin-top:20px;">Gerado por Meu Controle Financeiro em ${new Date().toLocaleString("pt-BR")}</p>
    </body></html>`;
  return downloadFile(filename, html, "application/msword");
}

// Abre a caixa de impressão do navegador com um layout pronto para "Salvar como PDF".
function buildPrintableHTML(logoSrc, title, subtitle, headers, rows, totalsHtml) {
  const theadCols = headers.map((h) => `<th>${h}</th>`).join("");
  const bodyRows = rows.map((r) => `<tr>${r.map((c) => `<td>${c ?? ""}</td>`).join("")}</tr>`).join("");
  return `<!DOCTYPE html>
    <html><head><meta charset="utf-8"><title>${title}</title>
    <style>
      body{font-family:Arial,Helvetica,sans-serif;color:#1c1c1c;padding:32px;}
      .header{display:flex;align-items:center;gap:14px;border-bottom:3px solid #0f2547;padding-bottom:14px;margin-bottom:18px;}
      .header img{width:44px;height:44px;}
      .header h1{margin:0;font-size:22px;color:#0f2547;}
      .header p{margin:2px 0 0;font-size:12px;color:#555;}
      table{width:100%;border-collapse:collapse;font-size:12px;}
      th{background:#0f2547;color:#fff;padding:8px;text-align:left;}
      td{padding:7px 8px;border-bottom:1px solid #e5e5e5;}
      tr:nth-child(even){background:#f7f8fa;}
      .totais{margin-top:16px;font-size:13px;}
      .totais b{color:#0f2547;}
      .rodape{margin-top:28px;font-size:10px;color:#999;}
      .aviso{background:#fef3c7;color:#92400e;padding:10px 14px;border-radius:8px;font-size:12px;margin-bottom:18px;}
      @media print{ .aviso{display:none;} }
    </style></head>
    <body>
      <p class="aviso">Se a impressão não abrir sozinha, aperte Ctrl+P (ou Cmd+P no Mac) e escolha "Salvar como PDF".</p>
      <div class="header"><img src="${logoSrc}" /><div><h1>${title}</h1><p>${subtitle}</p></div></div>
      <table><thead><tr>${theadCols}</tr></thead><tbody>${bodyRows}</tbody></table>
      ${totalsHtml || ""}
      <p class="rodape">Gerado por Meu Controle Financeiro em ${new Date().toLocaleString("pt-BR")}</p>
      <script>window.onload = () => setTimeout(() => window.print(), 400);</script>
    </body></html>`;
}

// Modal de exportação: tenta baixar o arquivo, mas sempre oferece copiar o
// conteúdo como alternativa garantida (o download automático pode ser
// bloqueado dependendo de onde o app está sendo aberto).
function ExportModal({ filename, content, mime, onClose }) {
  const { notify } = useContext(UIContext);
  const [tried, setTried] = useState(false);
  const taRef = useRef(null);

  const tryDownload = () => {
    const ok = downloadFile(filename, content, mime);
    setTried(true);
    notify(ok ? "Se nada abriu, use \"Copiar conteúdo\" abaixo." : "Download bloqueado neste ambiente — use \"Copiar conteúdo\".");
  };
  const copyAll = async () => {
    try {
      await navigator.clipboard.writeText(content);
      notify("Conteúdo copiado! Cole em um arquivo de texto ou planilha.");
    } catch (e) {
      if (taRef.current) { taRef.current.select(); document.execCommand("copy"); notify("Conteúdo selecionado e copiado."); }
    }
  };

  return (
    <Modal title={`Exportar: ${filename}`} onClose={onClose}>
      <p className="text-sm ts mb-3">Baixe o arquivo diretamente ou copie o conteúdo e cole em um bloco de notas / planilha — o que funcionar primeiro no seu navegador.</p>
      <div className="flex gap-2 mb-3">
        <button onClick={tryDownload} className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: NAVY }}><Download size={15} /> Baixar arquivo</button>
        <button onClick={copyAll} className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium btn-outline"><FileText size={15} /> Copiar conteúdo</button>
      </div>
      <textarea ref={taRef} readOnly value={content} className="input2 font-mono text-xs" rows={10} onFocus={(e) => e.target.select()} />
      <p className="text-[11px] tm mt-2">Dica: se o download não abrir nada, clique dentro do texto acima, selecione tudo (Ctrl/Cmd+A) e copie (Ctrl/Cmd+C).</p>
    </Modal>
  );
}

