          return (
            <button key={it.id} onClick={() => { setPage(it.id); if (!isDesktop) setOpen(false); }}
              className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm"
              style={active
                ? { background: `linear-gradient(135deg, ${GOLD_LIGHT}, ${GOLD})`, color: NAVY_DARK, fontWeight: 700, boxShadow: "0 4px 14px -2px rgba(201,162,39,0.45)" }
                : { color: "#aebbd6" }}>
              <Icon size={17} strokeWidth={active ? 2.4 : 2} />{it.label}
            </button>
          );
