    <Modal title={editing ? "Editar lançamento padrão" : "Novo lançamento padrão"} onClose={onClose}>
      <Field label="Descrição do lançamento"><input className="input2" value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Ex: Conta de luz" /></Field>
      <Field label="Categoria onde ele entra">
        <select className="input2" value={catId} onChange={(e) => setCatId(e.target.value)}>
          <option value="">Selecionar…</option>
          <optgroup label="Despesas">{categories.filter((c) => c.tipo === "despesa").map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</optgroup>
          <optgroup label="Receitas">{categories.filter((c) => c.tipo === "receita").map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</optgroup>
        </select>
      </Field>
      {editing && (
        <label className="flex items-start gap-2 mb-3 text-xs ts">
          <input type="checkbox" className="mt-0.5" checked={aplicar} onChange={(e) => setAplicar(e.target.checked)} />
          <span>Aplicar também aos lançamentos que já fiz com essa descrição (muda o nome e a categoria deles).</span>
        </label>
      )}
      <ModalActions onClose={onClose} disabled={!valid} onSave={() => onSave({ nome: nome.trim(), categoriaId: catId }, aplicar)} />
    </Modal>
