// ==================== IMPORTAR EXTRATO (CSV / OFX) ====================
function ImportExtratoModal({ contas, cartoes, categories, onClose, onImport }) {
  const [step, setStep] = useState(1); // 1: arquivo, 2: mapear colunas (CSV), 3: prévia
  const [origemTipo, setOrigemTipo] = useState((contas || [])[0] ? "conta" : (cartoes || [])[0] ? "cartao" : "outro");
  const [origemId, setOrigemId] = useState((contas || [])[0]?.id || "");
  const [origemTexto, setOrigemTexto] = useState("");
  const catReceitas = categories.filter((c) => c.tipo === "receita");
  const catDespesas = categories.filter((c) => c.tipo === "despesa");
  const [categoriaReceitaId, setCategoriaReceitaId] = useState(catReceitas[0]?.id || "");
  const [categoriaDespesaId, setCategoriaDespesaId] = useState(catDespesas[0]?.id || "");
  const [headers, setHeaders] = useState([]);
  const [rawRows, setRawRows] = useState([]);
  const [colData, setColData] = useState("");
  const [colDesc, setColDesc] = useState("");
  const [colValor, setColValor] = useState("");
  const [detected, setDetected] = useState([]);
  const [erro, setErro] = useState("");
  const fileRef = useRef(null);

  const mudarOrigemTipo = (novoTipo) => {
    setOrigemTipo(novoTipo);
    if (novoTipo === "conta") setOrigemId(contas[0]?.id || "");
    else if (novoTipo === "cartao") setOrigemId(cartoes[0]?.id || "");
    else setOrigemId("");
  };

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setErro("");
    const text = await file.text();
    if (/\.ofx$/i.test(file.name) || /<OFX>/i.test(text)) {
      const txs = parseOFX(text);
      if (txs.length === 0) { setErro("Não consegui encontrar lançamentos nesse arquivo OFX."); return; }
      setDetected(txs.map((t) => ({ ...t, selected: true })));
      setStep(3);
      return;
    }
    Papa.parse(text, {
      header: true, skipEmptyLines: true,
      complete: (res) => {
        if (!res.data.length) { setErro("Arquivo CSV vazio ou não reconhecido."); return; }
        const hdrs = res.meta.fields || [];
        setHeaders(hdrs);
        setRawRows(res.data);
        const findCol = (candidates) => hdrs.find((h) => candidates.some((c) => h.toLowerCase().includes(c)));
        setColData(findCol(["data", "date", " dt"]) || hdrs[0] || "");
        setColDesc(findCol(["descri", "histór", "histor", "memo", "lançamento", "lancamento", "nome"]) || hdrs[1] || "");
        setColValor(findCol(["valor", "amount", "value"]) || hdrs[2] || "");
        setStep(2);
      },
    });
  };

  const gerarDaCSV = () => {
    if (!colData || !colDesc || !colValor) { setErro("Selecione as três colunas antes de continuar."); return; }
    const txs = rawRows.map((row) => {
      const data = parseDataBR(row[colData]);
      const valorRaw = parseValorBR(row[colValor]);
      return { data, descricao: (row[colDesc] || "").toString().trim() || "Lançamento importado", valor: Math.abs(valorRaw), tipo: valorRaw >= 0 ? "receita" : "despesa", selected: true };
    }).filter((t) => t.data && !isNaN(t.valor) && t.valor > 0);
    if (txs.length === 0) { setErro("Não encontrei lançamentos válidos com essas colunas. Confira se escolheu certo."); return; }
    setErro("");
    setDetected(txs);
    setStep(3);
  };

  const toggleSel = (i) => setDetected((d) => d.map((t, idx) => idx === i ? { ...t, selected: !t.selected } : t));
  const toggleTipo = (i) => setDetected((d) => d.map((t, idx) => idx === i ? { ...t, tipo: t.tipo === "receita" ? "despesa" : "receita" } : t));
  const selecionadosCount = detected.filter((t) => t.selected).length;

  const confirmar = () => {
    const selecionados = detected.filter((t) => t.selected);
    if (selecionados.length === 0) { setErro("Selecione ao menos um lançamento."); return; }
    if (origemTipo === "outro" ? !origemTexto.trim() : !origemId) { setErro("Informe a origem (conta, cartão ou texto livre)."); return; }
    const itens = selecionados.map((t) => ({
      descricao: t.descricao,
      tipo: t.tipo,
      categoriaId: t.tipo === "receita" ? categoriaReceitaId : categoriaDespesaId,
      origemTipo, origemId: origemTipo === "outro" ? null : origemId, origemTexto: origemTipo === "outro" ? origemTexto.trim() : "",
      afetaSaldo: true,
      valor: t.valor,
      data: t.data,
      status: "concluido",
    }));
    onImport(itens);
  };

  return (
    <Modal title="Importar Extrato (CSV ou OFX)" onClose={onClose}>
      {step === 1 && (
        <>
          <p className="text-sm ts mb-3">Exporte o extrato do seu banco em <b>CSV</b> ou <b>OFX</b> (procure "exportar" no app/site do banco — não é o PDF). Depois selecione o arquivo aqui.</p>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <Field label="Origem">
              <select className="input2" value={origemTipo} onChange={(e) => mudarOrigemTipo(e.target.value)}>
                <option value="conta">Conta bancária</option>
                <option value="cartao">Cartão de crédito</option>
                <option value="outro">Outro</option>
              </select>
            </Field>
            {origemTipo === "conta" && (
              <Field label="Qual conta">
                {(!contas || contas.length === 0) ? <p className="text-xs tm mt-2">Nenhuma conta cadastrada.</p> : (
                  <select className="input2" value={origemId} onChange={(e) => setOrigemId(e.target.value)}>{contas.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
                )}
              </Field>
            )}
            {origemTipo === "cartao" && (
              <Field label="Qual cartão">
                {(!cartoes || cartoes.length === 0) ? <p className="text-xs tm mt-2">Nenhum cartão cadastrado.</p> : (
                  <select className="input2" value={origemId} onChange={(e) => setOrigemId(e.target.value)}>{cartoes.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
                )}
              </Field>
            )}
            {origemTipo === "outro" && (
              <Field label="Descreva a origem"><input className="input2" value={origemTexto} onChange={(e) => setOrigemTexto(e.target.value)} placeholder="Ex: Dinheiro" /></Field>
            )}
          </div>
          {origemTipo === "conta" && <p className="text-[11px] tm -mt-2 mb-3">Os lançamentos importados entram como "Concluído" e vão somar automaticamente ao saldo dessa conta.</p>}
          <button onClick={() => fileRef.current.click()} className="input2 flex items-center justify-center gap-2 py-8 text-sm ts" style={{ borderStyle: "dashed" }}>
            <UploadCloud size={18} /> Clique para escolher o arquivo (.csv ou .ofx)
          </button>
          <input ref={fileRef} type="file" accept=".csv,.ofx,text/csv" className="hidden" onChange={handleFile} />
          {erro && <p className="text-xs text-red-500 mt-2">{erro}</p>}
          <p className="text-[11px] tm mt-3">Ainda não sei ler PDF de extrato de forma confiável (cada banco formata diferente) — por isso peço CSV ou OFX, que são mais precisos.</p>
        </>
      )}

      {step === 2 && (
        <>
          <p className="text-sm ts mb-3">Achei {rawRows.length} linha(s) no arquivo. Confirme qual coluna é qual:</p>
          <Field label="Coluna da data"><select className="input2" value={colData} onChange={(e) => setColData(e.target.value)}>{headers.map((h) => <option key={h} value={h}>{h}</option>)}</select></Field>
          <Field label="Coluna da descrição"><select className="input2" value={colDesc} onChange={(e) => setColDesc(e.target.value)}>{headers.map((h) => <option key={h} value={h}>{h}</option>)}</select></Field>
          <Field label="Coluna do valor"><select className="input2" value={colValor} onChange={(e) => setColValor(e.target.value)}>{headers.map((h) => <option key={h} value={h}>{h}</option>)}</select></Field>
          {erro && <p className="text-xs text-red-500 mb-2">{erro}</p>}
          <div className="flex justify-end gap-2 mt-2">
            <button onClick={() => setStep(1)} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Voltar</button>
            <button onClick={gerarDaCSV} className="px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: NAVY }}>Continuar</button>
          </div>
        </>
      )}

      {step === 3 && (
        <>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <Field label="Categoria padrão p/ receitas"><select className="input2" value={categoriaReceitaId} onChange={(e) => setCategoriaReceitaId(e.target.value)}>{catReceitas.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
            <Field label="Categoria padrão p/ despesas"><select className="input2" value={categoriaDespesaId} onChange={(e) => setCategoriaDespesaId(e.target.value)}>{catDespesas.map((c) => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field>
          </div>
          <p className="text-xs tm mb-2">{detected.length} lançamento(s) encontrado(s) · {selecionadosCount} selecionado(s). Desmarque o que não quiser importar, ou clique no tipo pra corrigir receita/despesa. Todos entram como categoria padrão acima — dá pra ajustar depois em Lançamentos.</p>
          <div className="overflow-y-auto border rounded-lg" style={{ maxHeight: 260, borderColor: "var(--card-border)" }}>
            <table className="w-full text-xs">
              <thead>
                <tr className="text-left tm uppercase border-b sticky top-0" style={{ borderColor: "var(--card-border)", background: "var(--card-bg)" }}>
                  <th className="py-2 px-2 w-6"></th><th className="py-2 px-2">Data</th><th className="py-2 px-2">Descrição</th><th className="py-2 px-2">Valor</th><th className="py-2 px-2">Tipo</th>
                </tr>
              </thead>
              <tbody>
                {detected.map((t, i) => (
                  <tr key={i} className="border-b last:border-0" style={{ borderColor: "var(--card-border)", opacity: t.selected ? 1 : 0.4 }}>
                    <td className="py-1.5 px-2"><input type="checkbox" checked={t.selected} onChange={() => toggleSel(i)} /></td>
                    <td className="py-1.5 px-2 ts whitespace-nowrap">{fmtDate(t.data)}</td>
                    <td className="py-1.5 px-2 tp">{t.descricao}</td>
                    <td className="py-1.5 px-2 tp whitespace-nowrap">{brl(t.valor)}</td>
                    <td className="py-1.5 px-2">
                      <button onClick={() => toggleTipo(i)}>
                        {t.tipo === "receita" ? <Badge color="#16a34a" bg="#dcfce7">Receita</Badge> : <Badge color="#dc2626" bg="#fee2e2">Despesa</Badge>}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {erro && <p className="text-xs text-red-500 mt-2">{erro}</p>}
          <div className="flex justify-end gap-2 mt-4">
            <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Cancelar</button>
            <button onClick={confirmar} disabled={selecionadosCount === 0} className="px-4 py-2 rounded-lg text-sm font-medium text-white disabled:opacity-40" style={{ background: NAVY }}>Importar {selecionadosCount} lançamento(s)</button>
          </div>
        </>
      )}
    </Modal>
  );
}

// ==================== CONFIGURAÇÕES ====================
function ConfiguracoesPage({ data, currentUser, canAdmin, canWrite, setPage, onEditProfile, onReset, onClear, onExport, onImport, onSaveUser, onDeleteUser, onAddUser, onEditUser, onSaveDevicePin, onSaveNotificacoes, categoriasProps }) {
  const { confirm } = useContext(UIContext);
  const [tab, setTab] = useState("perfil");
  const tabs = [
    { id: "perfil", label: "Perfil" },
    { id: "usuarios", label: "Usuários", admin: true },
    { id: "permissoes", label: "Permissões", admin: true },
    { id: "auditoria", label: "Auditoria", admin: true },
    { id: "notificacoes", label: "Notificações" },
    { id: "categorias", label: "Categorias" },
    { id: "backup", label: "Backup & Dados", admin: true },
  ];
  return (
    <div className="max-w-3xl flex flex-col gap-4">
      <div className="flex gap-2 flex-wrap">
        {tabs.map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)} className="px-3 py-1.5 rounded-full text-xs font-medium"
            style={tab === t.id ? { background: NAVY, color: "#fff" } : { background: "var(--card-bg)", color: "var(--text-secondary)", border: "1px solid var(--card-border)" }}>
            {t.label}
          </button>
        ))}
      </div>

      {tab === "perfil" && (
        <div className="card rounded-xl p-5 flex items-center gap-4">
          {currentUser.avatar ? <img src={currentUser.avatar} className="w-14 h-14 rounded-full object-cover" /> : <div className="w-14 h-14 rounded-full flex items-center justify-center text-lg font-semibold text-white" style={{ background: NAVY }}>{(currentUser.nome || "U")[0].toUpperCase()}</div>}
          <div className="flex-1">
            <p className="font-semibold tp">{currentUser.nome}</p>
            <p className="text-xs ts">{ROLE_LABELS[currentUser.role]}</p>
          </div>
          <button onClick={onEditProfile} className="text-sm px-3 py-1.5 rounded-lg btn-outline">Editar</button>
        </div>
      )}

      {tab === "usuarios" && (canAdmin ? (
        <div className="flex flex-col gap-4">
          <div className="flex justify-end"><button onClick={onAddUser} className="flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: NAVY }}><Plus size={16} /> Novo Usuário</button></div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {data.users.map((u) => (
              <div key={u.id} className="card rounded-xl p-4 flex items-center gap-3">
                {u.avatar ? <img src={u.avatar} className="w-11 h-11 rounded-full object-cover" /> : <div className="w-11 h-11 rounded-full flex items-center justify-center font-semibold text-white" style={{ background: NAVY }}>{u.nome[0].toUpperCase()}</div>}
                <div className="flex-1 min-w-0">
                  <p className="font-medium tp truncate">{u.nome} {u.id === currentUser.id && <span className="text-[10px] tm">(você)</span>}</p>
                  <p className="text-xs ts">{ROLE_LABELS[u.role]}{u.email ? ` · ${u.email}` : ""}</p>
                </div>
                <IconBtn onClick={() => onEditUser(u)}><Pencil size={15} /></IconBtn>
                <IconBtn onClick={async () => { if (await confirm(`Excluir o usuário "${u.nome}"?`)) onDeleteUser(u.id); }}><Trash2 size={15} /></IconBtn>
              </div>
            ))}
          </div>
        </div>
      ) : <RestrictedTab />)}

      {tab === "permissoes" && (canAdmin ? <PermissoesTab setTab={setTab} /> : <RestrictedTab />)}
      {tab === "auditoria" && (canAdmin ? <AuditoriaTab log={data.auditLog} /> : <RestrictedTab />)}
      {tab === "notificacoes" && <NotificacoesTab settings={data.settings.notificacoes} onSave={onSaveNotificacoes} readOnly={!canAdmin} />}
      {tab === "categorias" && (
        <CategoriasPage {...categoriasProps} />
      )}
      {tab === "backup" && (canAdmin ? <BackupTab devicePin={data.devicePin} onExport={onExport} onImport={onImport} onReset={onReset} onClear={onClear} onSaveDevicePin={onSaveDevicePin} /> : <RestrictedTab />)}

      <div className="flex items-center gap-2 text-xs tm px-1">
        <Sparkles size={13} /> Meu Controle Financeiro v{APP_VERSION} — feito com sua identidade visual.
      </div>
    </div>
  );
}

function RestrictedTab() {
  return (
    <div className="card rounded-xl p-8 text-center">
      <Lock size={22} className="mx-auto tm mb-2" />
      <p className="text-sm ts">Área restrita a administradores.</p>
    </div>
  );
}

function PermissoesTab({ setTab }) {
  const rows = [
    ["Ver dashboard e relatórios", true, true, true],
    ["Criar / editar / excluir lançamentos, contas, categorias", true, true, false],
    ["Gerenciar transferências, orçamentos e metas", true, true, false],
    ["Gerenciar usuários e permissões", true, false, false],
    ["Ver auditoria completa", true, false, false],
    ["Backup, importar, restaurar ou apagar dados", true, false, false],
  ];
  return (
    <div className="card rounded-xl p-5 overflow-x-auto">
      <div className="flex justify-between items-start flex-wrap gap-3 mb-3">
        <div>
          <h3 className="font-semibold tp">O que cada papel pode fazer</h3>
          <p className="text-xs tm mt-0.5">Esta tabela é fixa (regras do sistema) — não dá pra editar aqui.</p>
        </div>
        <button onClick={() => setTab("usuarios")} className="text-xs px-3 py-1.5 rounded-lg btn-outline flex-none">Trocar o papel de alguém →</button>
      </div>
      <table className="w-full text-sm">
        <thead>
          <tr className="text-left tm text-xs uppercase border-b" style={{ borderColor: "var(--card-border)" }}>
            <th className="py-2 pr-4 font-medium">Ação</th>
            <th className="py-2 px-2 font-medium text-center">Admin</th>
            <th className="py-2 px-2 font-medium text-center">Editor</th>
            <th className="py-2 px-2 font-medium text-center">Visualizador</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(([label, a, e, v]) => (
            <tr key={label} className="border-b last:border-0" style={{ borderColor: "var(--card-border)" }}>
              <td className="py-2.5 pr-4 ts">{label}</td>
              <td className="py-2.5 px-2 text-center">{a ? <CheckCircle2 size={15} className="inline text-green-600" /> : <X size={15} className="inline tm" />}</td>
              <td className="py-2.5 px-2 text-center">{e ? <CheckCircle2 size={15} className="inline text-green-600" /> : <X size={15} className="inline tm" />}</td>
              <td className="py-2.5 px-2 text-center">{v ? <CheckCircle2 size={15} className="inline text-green-600" /> : <X size={15} className="inline tm" />}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="text-xs tm mt-3">Isso organiza o uso do sistema por vários familiares/colaboradores no mesmo aparelho — não é uma autenticação segura de servidor.</p>
      <p className="text-xs tm mt-1">Quer que alguém tenha mais ou menos acesso? Vá em <b>Usuários</b>, edite a pessoa e mude o papel dela para Administrador, Editor ou Visualizador.</p>
    </div>
  );
}

function AuditoriaTab({ log }) {
  const [filtro, setFiltro] = useState("");
  const filtered = (log || []).filter((l) => !filtro || l.userNome.toLowerCase().includes(filtro.toLowerCase()));
  return (
    <div className="card rounded-xl p-5">
      <div className="flex justify-between items-center mb-3 flex-wrap gap-2">
        <h3 className="font-semibold tp">Histórico de ações ({filtered.length})</h3>
        <input className="input2 w-48" placeholder="Filtrar por usuário…" value={filtro} onChange={(e) => setFiltro(e.target.value)} />
      </div>
      {filtered.length === 0 ? <EmptyState text="Nenhuma ação registrada ainda." /> : (
        <div className="overflow-x-auto max-h-[420px] overflow-y-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left tm text-xs uppercase border-b sticky top-0" style={{ borderColor: "var(--card-border)", background: "var(--card-bg)" }}>
                <th className="py-2 pr-4 font-medium">Quando</th><th className="py-2 pr-4 font-medium">Usuário</th>
                <th className="py-2 pr-4 font-medium">Ação</th><th className="py-2 pr-4 font-medium">Detalhe</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((l) => (
                <tr key={l.id} className="border-b last:border-0" style={{ borderColor: "var(--card-border)" }}>
                  <td className="py-2 pr-4 ts whitespace-nowrap">{new Date(l.ts).toLocaleString("pt-BR")}</td>
                  <td className="py-2 pr-4 tp">{l.userNome}</td>
                  <td className="py-2 pr-4 ts">{l.acao}</td>
                  <td className="py-2 pr-4 tm">{l.detalhe}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <p className="text-xs tm mt-3">Mantemos as últimas 500 ações. O registro fica salvo neste mesmo dispositivo.</p>
    </div>
  );
}

function NotificacoesTab({ settings, onSave, readOnly }) {
  const [diasAntecedencia, setDias] = useState(settings.diasAntecedencia);
  const [alertaVencido, setAlertaVencido] = useState(settings.alertaVencido);
  const [alertaOrcamento, setAlertaOrcamento] = useState(settings.alertaOrcamento);
  const [alertaSaldoBaixo, setAlertaSaldoBaixo] = useState(settings.alertaSaldoBaixo);
  const [saldoMinimo, setSaldoMinimo] = useState(settings.saldoMinimo);
  return (
    <div className="card rounded-xl p-5 flex flex-col gap-4">
      <div>
        <label className="flex items-center gap-2 text-sm tp"><input type="checkbox" disabled={readOnly} checked={alertaVencido} onChange={(e) => setAlertaVencido(e.target.checked)} /> Avisar sobre lançamentos vencidos</label>
      </div>
      <div>
        <label className="flex items-center gap-2 text-sm tp"><input type="checkbox" disabled={readOnly} checked={alertaOrcamento} onChange={(e) => setAlertaOrcamento(e.target.checked)} /> Avisar quando um orçamento estourar</label>
      </div>
      <div>
        <label className="flex items-center gap-2 text-sm tp"><input type="checkbox" disabled={readOnly} checked={alertaSaldoBaixo} onChange={(e) => setAlertaSaldoBaixo(e.target.checked)} /> Avisar sobre saldo baixo em contas</label>
        {alertaSaldoBaixo && <div className="mt-2 max-w-[200px]"><Field label="Saldo mínimo (R$)"><input disabled={readOnly} className="input2" type="number" value={saldoMinimo} onChange={(e) => setSaldoMinimo(e.target.value)} /></Field></div>}
      </div>
      <div className="max-w-[220px]">
        <Field label="Avisar com quantos dias de antecedência sobre vencimentos"><input disabled={readOnly} className="input2" type="number" min="1" max="30" value={diasAntecedencia} onChange={(e) => setDias(e.target.value)} /></Field>
      </div>
      {!readOnly && (
        <div><button onClick={() => onSave({ diasAntecedencia: parseInt(diasAntecedencia, 10) || 7, alertaVencido, alertaOrcamento, alertaSaldoBaixo, saldoMinimo: parseFloat(saldoMinimo) || 0 })} className="px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: NAVY }}>Salvar preferências</button></div>
      )}
      {readOnly && <p className="text-xs tm">Apenas administradores podem alterar estas preferências.</p>}
    </div>
  );
}

function BackupTab({ devicePin, onExport, onImport, onReset, onClear, onSaveDevicePin }) {
  const fileRef = useRef(null);
  const [pinOn, setPinOn] = useState(!!devicePin.enabled);
  const [pin, setPin] = useState("");
  const [pinConfirm, setPinConfirm] = useState("");
  const [error, setError] = useState("");

  const savePin = () => {
    setError("");
    if (!pinOn) { onSaveDevicePin(null); return; }
    if (pin.length < 4) { setError("O PIN deve ter pelo menos 4 dígitos."); return; }
    if (pin !== pinConfirm) { setError("Os PINs não coincidem."); return; }
    onSaveDevicePin(pin);
    setPin(""); setPinConfirm("");
  };

  return (
    <div className="flex flex-col gap-4">
      <div className="card rounded-xl p-5">
        <h3 className="font-semibold tp flex items-center gap-2"><Lock size={16} /> PIN deste aparelho</h3>
        <p className="text-sm ts mt-1 mb-3">Trava a tela inicial neste dispositivo (protege visualização local, não é login em nuvem).</p>
        <label className="flex items-center gap-2 text-sm tp mb-3"><input type="checkbox" checked={pinOn} onChange={(e) => setPinOn(e.target.checked)} /> Ativar PIN</label>
        {pinOn && (
          <div className="grid grid-cols-2 gap-3 max-w-sm">
            <Field label={devicePin.hash ? "Novo PIN (opcional)" : "Definir PIN"}><input className="input2" type="password" inputMode="numeric" maxLength={6} value={pin} onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))} /></Field>
            <Field label="Confirmar PIN"><input className="input2" type="password" inputMode="numeric" maxLength={6} value={pinConfirm} onChange={(e) => setPinConfirm(e.target.value.replace(/\D/g, ""))} /></Field>
          </div>
        )}
        {error && <p className="text-xs text-red-500 mb-2">{error}</p>}
        <button onClick={savePin} className="px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: NAVY }}>Salvar segurança</button>
      </div>

      <div className="card rounded-xl p-5">
        <h3 className="font-semibold tp flex items-center gap-2"><Download size={16} /> Exportar backup</h3>
        <p className="text-sm ts mt-1 mb-3">Baixe um arquivo JSON com todos os seus dados, para guardar ou migrar de dispositivo.</p>
        <button onClick={onExport} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Baixar backup (.json)</button>
      </div>

      <div className="card rounded-xl p-5">
        <h3 className="font-semibold tp flex items-center gap-2"><Upload size={16} /> Importar backup</h3>
        <p className="text-sm ts mt-1 mb-3">Restaure a partir de um arquivo exportado anteriormente. Isso substitui os dados atuais.</p>
        <input ref={fileRef} type="file" accept="application/json" className="hidden" onChange={(e) => e.target.files?.[0] && onImport(e.target.files[0])} />
        <button onClick={() => fileRef.current.click()} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Selecionar arquivo</button>
      </div>

      <div className="card rounded-xl p-5">
        <h3 className="font-semibold tp">Restaurar dados de exemplo</h3>
        <p className="text-sm ts mt-1 mb-3">Apaga seus dados atuais e recoloca os dados de exemplo do início.</p>
        <button onClick={onReset} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Restaurar exemplo</button>
      </div>

      <div className="card rounded-xl p-5" style={{ borderColor: "#fca5a5" }}>
        <h3 className="font-semibold" style={{ color: "#dc2626" }}>Apagar todos os dados</h3>
        <p className="text-sm ts mt-1 mb-3">Remove contas, categorias, lançamentos, orçamentos e metas. Não pode ser desfeito.</p>
        <button onClick={onClear} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-red-600">Apagar tudo</button>
      </div>
    </div>
  );
}

// ==================== COMPONENTES COMPARTILHADOS ====================
function IconBtn({ children, onClick }) {
  return <button onClick={onClick} className="w-7 h-7 rounded-md flex items-center justify-center tm hover-row"><span className="flex">{children}</span></button>;
}
function MonthYearPicker({ value, onChange }) {
  const [ano, mes] = value.split("-");
  const nomesMes = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];
  const anoAtual = new Date().getFullYear();
  const anos = Array.from({ length: 6 }, (_, i) => anoAtual - 3 + i);
  return (
    <div className="flex gap-2">
      <select className="input2 w-auto" value={mes} onChange={(e) => onChange(`${ano}-${e.target.value}`)}>
        {nomesMes.map((nome, i) => <option key={i} value={String(i + 1).padStart(2, "0")}>{nome}</option>)}
      </select>
      <select className="input2 w-auto" value={ano} onChange={(e) => onChange(`${e.target.value}-${mes}`)}>
        {anos.map((a) => <option key={a} value={a}>{a}</option>)}
      </select>
    </div>
  );
}
function EmptyState({ text }) {
  return (
    <div className="py-14 flex flex-col items-center gap-3 text-center px-6">
      <div className="w-12 h-12 rounded-2xl flex items-center justify-center" style={{ background: "var(--hover-bg)" }}>
        <Search size={20} className="tm" />
      </div>
      <p className="text-sm tm max-w-xs">{text}</p>
    </div>
  );
}
function Field({ label, children }) {
  return <label className="block mb-3"><span className="block text-xs font-medium ts mb-1">{label}</span>{children}</label>;
}
function ModalActions({ onClose, onSave, disabled }) {
  return (
    <div className="flex justify-end gap-2 mt-5">
      <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium btn-outline">Cancelar</button>
      <button onClick={onSave} disabled={disabled} className="px-4 py-2 rounded-lg text-sm font-semibold text-white disabled:opacity-40" style={{ background: `linear-gradient(135deg, ${NAVY_LIGHT}, ${NAVY_DARK})`, boxShadow: "0 4px 12px -2px rgba(15,37,71,0.4)" }}>Salvar</button>
    </div>
  );
}
function Modal({ title, children, onClose }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: "rgba(10,20,40,0.55)", backdropFilter: "blur(3px)", WebkitBackdropFilter: "blur(3px)" }}>
      <div className="card rounded-2xl w-full max-w-md p-6 max-h-[90vh] overflow-y-auto" style={{ boxShadow: "0 24px 60px -12px rgba(0,0,0,0.35)" }}>
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold tp text-base flex items-center gap-2">
            <span className="w-1 h-4 rounded-full" style={{ background: `linear-gradient(180deg, ${GOLD_LIGHT}, ${GOLD})` }} />
            {title}
          </h3>
          <button onClick={onClose} className="tm hover:opacity-70"><X size={20} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}
